begin;
-- Match venue identifiers are populated even where the club's optional stadium field is blank.
create or replace function public.news_context_image(p_club uuid) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select coalesce((select jsonb_build_object('image_url',s.exterior_image_url,'image_kind','context','image_credit',s.image_credit,'image_source_url',s.image_source_url,'image_license',s.image_license_url,'image_license_url',s.image_license_url,'image_rights_verified',true) from stadiums s join (select m.stadium,count(*) as appearances,max(m.kickoff) as recent from matches m where m.home_club_id=p_club and m.kickoff>now()-interval '1 year' and m.stadium is not null group by m.stadium) venues on venues.stadium=s.provider_name where s.exterior_image_url is not null and s.image_credit is not null and s.image_source_url is not null and s.image_license_url is not null order by venues.appearances desc,venues.recent desc limit 1),jsonb_build_object('image_url','https://fhfpm8x522-sys.github.io/4545-app/email-stadium-4545.png','image_kind','brand','image_credit','45:45 · תמונת מותג שהועלתה בידי בעל האתר','image_source_url','https://fhfpm8x522-sys.github.io/4545-app/','image_license','חומר מותג שנמסר לפרויקט 45:45','image_rights_verified',true));
$$;
with images as (select n.id,news_context_image(n.club_id) as p from news_items n where n.image_kind='brand' and n.ai_group_key like 'gdelt:%') update news_items n set image_url=i.p->>'image_url',image_kind='context',image_credit=i.p->>'image_credit',image_source_url=i.p->>'image_source_url',image_license=i.p->>'image_license',image_license_url=i.p->>'image_license_url' from images i where n.id=i.id and i.p->>'image_kind'='context';
commit;
